// Generated by tools/prepare_assets.py and tools/prepare_role_assets.py
use super::SpriteAsset;
use crate::content::{self, TurnMode};

pub fn shadow_form(hero: usize, awake_visible: bool, mode: TurnMode) -> bool {
    if hero == content::NUN {
        if awake_visible {
            mode != TurnMode::Rational
        } else {
            mode == TurnMode::Frenzy
        }
    } else {
        awake_visible
    }
}

#[cfg(test)]
mod nun_visual_tests {
    use super::*;

    #[test]
    fn nun_uses_shadow_only_during_frenzy_or_unchecked_madness() {
        assert!(!shadow_form(content::NUN, false, TurnMode::Normal));
        assert!(shadow_form(content::NUN, false, TurnMode::Frenzy));
        assert!(shadow_form(content::NUN, true, TurnMode::Normal));
        assert!(!shadow_form(content::NUN, true, TurnMode::Rational));
        assert!(!shadow_form(content::KNIGHT, false, TurnMode::Frenzy));
    }
}

